  UNIQUE INDEX uq_assessment_attempt_external_attempt_ref (external_attempt_ref) WHERE deleted_at IS NULL AND (external_attempt_ref IS NOT NULL),
  INDEX idx_assessment_attempt_assessment_id_score_value (assessment_id, score_value DESC) WHERE deleted_at IS NULL AND graded_at IS NOT NULL,
