  CONSTRAINT fk_resume_root_resume_id FOREIGN KEY (root_resume_id) REFERENCES resume (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_resume_parent_resume_id FOREIGN KEY (parent_resume_id) REFERENCES resume (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
