CREATE TABLE IF NOT EXISTS referral (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  referrer_app_user_id UUID NOT NULL,
  referee_app_user_id UUID,
  job_requirement_id UUID,
  referral_status_id UUID NOT NULL,
  referral_channel_id UUID NOT NULL,
  referral_code STRING(24) NOT NULL,
  campaign_code STRING(40),
  referee_email STRING(254),
  invited_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  signed_up_at TIMESTAMPTZ,
  qualified_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL,
  signup_ip INET,
  CONSTRAINT pk_referral PRIMARY KEY (id),
  CONSTRAINT ck_referral_not_self CHECK (referee_app_user_id IS NULL OR referee_app_user_id <> referrer_app_user_id),
  CONSTRAINT ck_referral_email_lower CHECK (referee_email IS NULL OR referee_email = lower(referee_email)),
  CONSTRAINT ck_referral_timeline CHECK ((signed_up_at IS NULL OR signed_up_at >= invited_at) AND (qualified_at IS NULL OR signed_up_at IS NOT NULL) AND expires_at > invited_at),
  CONSTRAINT fk_referral_referrer_app_user_id FOREIGN KEY (referrer_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_referee_app_user_id FOREIGN KEY (referee_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_referral_status_id FOREIGN KEY (referral_status_id) REFERENCES referral_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_referral_channel_id FOREIGN KEY (referral_channel_id) REFERENCES referral_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_referral_referral_code (referral_code) WHERE deleted_at IS NULL AND (referral_code IS NOT NULL),
  UNIQUE INDEX uq_referral_referee_app_user_id (referee_app_user_id) WHERE deleted_at IS NULL AND (referee_app_user_id IS NOT NULL),
  UNIQUE INDEX uq_referral_referrer_app_user_id_referee_email (referrer_app_user_id, referee_email) WHERE deleted_at IS NULL AND (referee_email IS NOT NULL),
  INDEX idx_referral_referrer_app_user_id_invited_at (referrer_app_user_id, invited_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_referral_job_requirement_id (job_requirement_id) WHERE job_requirement_id IS NOT NULL
);
