  CONSTRAINT fk_candidate_shortlist_history_candidate_shortlist_item_id FOREIGN KEY (candidate_shortlist_item_id) REFERENCES candidate_shortlist_item (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_actor_app_user_id FOREIGN KEY (actor_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_shortlist_action_id FOREIGN KEY (shortlist_action_id) REFERENCES shortlist_action (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_from_shortlist_stage_id FOREIGN KEY (from_shortlist_stage_id) REFERENCES shortlist_stage (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_to_shortlist_stage_id FOREIGN KEY (to_shortlist_stage_id) REFERENCES shortlist_stage (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_from_candidate_shortlist_fo_f8f7 FOREIGN KEY (from_candidate_shortlist_folder_id) REFERENCES candidate_shortlist_folder (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_candidate_shortlist_history_to_candidate_shortlist_folder_id FOREIGN KEY (to_candidate_shortlist_folder_id) REFERENCES candidate_shortlist_folder (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_candidate_shortlist_history_candidate_shortlist_item_id (candidate_shortlist_item_id, occurred_at DESC),
  INDEX idx_candidate_shortlist_history_organisation_id_occurred_at (organisation_id, occurred_at DESC),
  INDEX idx_candidate_shortlist_history_candidate_profile_id (candidate_profile_id),
  INDEX idx_candidate_shortlist_history_occurred_at (occurred_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_candidate_shortlist_history_actor_app_user_id (actor_app_user_id)
) WITH (ttl_expiration_expression = '(occurred_at + INTERVAL ''36 months'')', ttl_job_cron = '@daily');
